#!/usr/bin/env python3
"""Record this workspace build without inheriting another machine's Docker facts."""
import datetime,hashlib,json,os,shutil,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def info(p):return {'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def main():
    sdk=Path(os.environ['DEVKITPRO']);arm=Path(os.environ['DEVKITARM'])
    source={}
    for d in ('runtime','include','platform','content','tools','tests'):
        for p in sorted((ROOT/d).rglob('*')):
            if p.is_file() and p.suffix in ('.cpp','.hpp','.py','.gd','.json') and '__pycache__' not in p.parts and 'bin' not in p.parts:source[p.relative_to(ROOT).as_posix()]=info(p)['sha256']
    for n in ['CMakeLists.txt','Makefile','platform/ctr/Makefile','assets/cia.rsf']:source[n]=info(ROOT/n)['sha256']
    tools={n:info(Path(shutil.which(n))) for n in ('makerom','ctrtool','bannertool','tex3ds','3dsxtool','smdhtool')}
    result={'schema':1,'recorded_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Original opening plus first complete Lamp battle round; separate room/battle/round/audio resources; M0 excluded; observed steady menu60FPS in cloud emulator in cloud emulator','source_commit':None,'source_history':'Original handoff has no project Git metadata; no invented commit','upstream_source_lock':json.loads((ROOT/'upstream.lock').read_text()),'source_sha256':source,'host_compiler':subprocess.check_output(['g++','--version'],text=True).splitlines()[0],'arm_compiler':subprocess.check_output([str(arm/'bin/arm-none-eabi-g++'),'--version'],text=True).splitlines()[0],'sdk_versions':{'devkitARM':'r68','libctru':'2.7.0','citro2d':'1.7.0','citro3d':'1.7.1'},'sdk_libraries':{n:info(sdk/'libctru/lib'/n)for n in ['libctru.a','libcitro2d.a','libcitro3d.a']},'tools':tools,'bannertool_note':'Official release v1.2.2 archive, pinned SHA256 e4259c08fe8944ebadd5f4b96f9a8603e5427338074cfc46323fbbc3410d51ed; binary internal version v1.2.0','artifacts':{n:info(ROOT/n)for n in ['dist/encore-native.elf','dist/encore-native.3dsx','dist/encore-native.cia','dist/encore-native.smdh','romfs/data/opening.encroom','romfs/data/opening.encbattle','romfs/data/opening.encround','romfs/data/opening.encaudio']},'verification':{'host':'25/25 passed; final affected2/2 passed; reports/battle-round-integration/host-tests-final.txt andhost-tests-postfix.txt','asan_ubsan':'25/25 passed with ASAN_OPTIONS=detect_leaks=0; final affected2/2 passed; reports/battle-round-integration/sanitize-tests-final.txt andsanitize-tests-postfix.txt','leak_sanitizer':'unsupported ptrace environment; original failure retained','collision':'27 native cases/599 frames,1274 checks; latest reports/m4-collision-reference-3','world_flags':'2208 checks; reports/m4-world-flags-reference-final','cia_content':'content hashes pass;55 native RomFS files identical;3 homebrew test signatures invalid','emulator':'Azahar exact226e95fd build: source encounter, target selection, complete round and next menu, real enemy0HP result boundary; reports/battle-round-visual; steady menu60FPS observed; audio unavailable; not hardware validation','hardware':'not run','full_game':'not ported or validated','battle_entry':'1169 scoped checks against150 native Godotframes; no action execution','audio':'1679 data checks and381 host-adapter-double checks; actual NDSP unavailable without DSP component','remaining_rendering':'60FPS steady menu observed only in cloud emulator; transition/hardware performance unvalidated; enemy cosmetic random shake not implemented; no GPU pixel-exact claim','lamp_dialogue':'55 source-ordered actions/848 checks; final RequestBattle relative frame384','actor_actions':'20 native cases/10196 checks; reports/actor-actions-reference-9','camera':'12 native cases/3025 checks; reports/camera-reference-final'},'program_data_separation':{'native_pack':info(ROOT/'romfs/data/opening.encroom'),'sections':26,'production_content_headers':0,'texture_files':46,'indexed_images':2,'audio_streams':3,'battle_pack':info(ROOT/'romfs/data/opening.encbattle'),'round_pack':info(ROOT/'romfs/data/opening.encround'),'audio_pack':info(ROOT/'romfs/data/opening.encaudio'),'m0_in_ctr':False,'same_executable_proof':'reports/data-only-proof/runtime-proof.json','arm_objects_proof':'reports/data-only-proof/arm-objects-unchanged.json'},'bit_reproducibility':'Not claimed; makerom/build paths can vary'}
    result['verification']['battle_round']='6 native outcomes/action orders/RNG continuations; exact global RNG32253 checks;470 presentation checks including100 nativeHP/textframes; rewards/worldreturn/items/audio mapping pending'
    target=ROOT/'reports/ctr-toolchain-lock.json';previous=ROOT/'reports/pre-cloud-ctr-toolchain-lock.json'
    if target.exists() and not previous.exists():shutil.copyfile(target,previous)
    target.write_text(json.dumps(result,indent=2)+'\n');print('Recorded cloud build inputs and verification limits')
if __name__=='__main__':main()
